def esc(s):return html.escape(str(s or 'Not established'))
def lis(xs):return '<ul>'+''.join('<li>'+esc(x)+'</li>' for x in xs)+'</ul>'
def link(url,label):return '<a href="'+html.escape(url,quote=True)+'">'+esc(label)+'</a>'
def jf(x):return '<pre>'+esc(json.dumps(x,ensure_ascii=False,indent=2))+'</pre>'
parts=['<!doctype html><html lang="en"><meta charset="utf-8"><title>OpenMath morning judging inventory</title><style>body{font:16px/1.55 system-ui;color:#18222d;background:#f3f5f7;max-width:1150px;margin:40px auto;padding:0 24px}h1{font-size:36px;line-height:1.15}h2{margin-top:38px}section,details{background:white;border:1px solid #d5dce3;border-radius:12px;padding:20px;margin:14px 0}summary{font-weight:650;cursor:pointer}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:9px;text-align:left;border-bottom:1px solid #dde2e7;vertical-align:top}a{color:#165798}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f1f4f6;padding:12px;font-size:12px}small,.muted{color:#526575}input{padding:12px;width:calc(100% - 26px);font-size:16px;border:1px solid #a8b8c8;border-radius:8px}.alert{border-left:5px solid #ad5913;background:#fff7e9}.tag{font-size:12px;background:#e6edf3;padding:3px 6px;border-radius:5px}.stats{display:flex;gap:16px;flex-wrap:wrap}.stats b{font-size:26px}</style><h1>OpenMath: collected work and judging queue</h1><p>'+esc(NOW)+' · one-time morning collection · cutoff 06:00 CEST</p><div class="stats"><section><b>7</b> curated hills</section><section><b>115</b> climbs, not final entries</section><section><b>72</b> contact/account records</section><section><b>33</b> extra accounts checked</section></div>']
